// Smartphone Portrait
@media (max-width: 575px) {

    .rtc-container-responsivo {
        width: 100%;
        padding-left: 8px;
        padding-right: 8px;
        margin-left: auto;
        margin-right: auto;
    }

    .rtc-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
