.rtc-destacado {
    border: 1px solid black;
    padding: 5px;
}

.rtc-descricao {
    max-width: 100%;
    margin: 0;
    margin-top: 6px;
    padding-right: 5px;
    overflow: hidden;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
}

.rtc-titulo-forte {
  font-size: var(--font-size-scale-up-02); // 1.44em ou 20.16px
  font-weight: var(--font-weight-semi-bold); // 600
}

.rtc-titulo {
  font-size: var(--font-size-scale-up-01); // 1.2em ou 16.8px
  font-weight: var(--font-weight-medium); // 500
}

.rtc-subtitulo {
  font-size: var(--font-size-scale-down-01); // 0.833em ou 11.67px
  font-weight: var(--font-weight-regular); // 400
}

.rtc-gray-background {
  background-color: var(--color-secondary-03);
}

.rtc-light-gray-background {
  background-color: var(--color-secondary-02);
}

.rtc-separador-horizontal-0 {
  background-color: var(--gray-warm-10);
  height: 1px;
  width: 100%;
}

.rtc-label {
    font-weight: bold;
    color: #333333;
    padding: 0 0 4px;
}


