.rtc-border-black {
  border: 1px solid black;
}

.rtc-border-red {
  border: 1px solid red;
}

.rtc-border-green {
  border: 1px solid green;
}

.rtc-border-blue {
  border: 1px solid blue;
}

.rtc-border-bottom-1 {
  border-bottom: 1px solid var(--gray-warm-10);
}

.rtc-border-top-1 {
  border-bottom: 1px solid var(--gray-warm-10);
}

.rtc-border-radius-8 {
  border-radius: 8px;
}

// Camada 0: sem sombra
.rtc-elevacao-0 {
  box-shadow: none;
  background: var(--surface-default);
}

// Camada 1: sombra suave
.rtc-elevacao-1 {
  border-radius: 8px;
  box-shadow:
    0 var(--surface-offset-sm) var(--surface-blur-lg) 0 rgba(var(--pure-100-rgb), var(--surface-opacity-xs));
  background: var(--background);
}

// Camada 2: sombra média
.rtc-elevacao-2 {
  border-radius: 8px;
  box-shadow:
    0 var(--surface-offset-md) var(--surface-blur-lg) 0 rgba(var(--pure-100-rgb), var(--surface-opacity-xs));
  background: var(--background);
}

// Camada 3: sombra forte
.rtc-elevacao-3 {
  box-shadow:
    0 var(--surface-offset-lg) var(--surface-blur-lg) 0 rgba(var(--pure-100-rgb), var(--surface-opacity-xs));
  background: var(--surface-default);
}

// Camada 4: sombra mais intensa
.rtc-elevacao-4 {
  border-radius: 8px;
  box-shadow:
    0 var(--surface-offset-xl) var(--surface-blur-lg) 0 rgba(var(--pure-100-rgb), var(--surface-opacity-xs));
  background: var(--background);
}