.rtc-flex {
  display: flex;
  flex-direction: row;
  align-items: center; // alinhamento vertical
  justify-content: center; // alinhamento horizontal
}

.rtc-flex-column {
  display: flex;
  flex-direction: column;
}

.rtc-linha-flex {
  display: flex;
  flex-direction: row;
  gap: 10px;
}

.rtc-flex-right {
  display: flex;
  flex-direction: row;
  justify-content: flex-end;
  align-items: center;
}

.rtc-flex-left {
  display: flex;
  flex-direction: row;
  justify-content: flex-start;
  align-items: center;
}

.rtc-flex-center {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: stretch;
}

.rtc-flex-center-1 {
  display: flex;
  flex-direction: row;
  justify-content: center; // para alinhar horizontalmente
  align-items: center;  // para alinhar verticalmente
  height: 100%; // para alinhar verticalmente
  //width: 100%;
}

.rtc-flex-center-2 {
  display: flex;
  flex-direction: row;
  justify-content: center; // para alinhar horizontalmente
  align-items: flex-end;  // para alinhar verticalmente
  height: 100%; // para alinhar verticalmente
  //width: 100%;
}

.rtc-flex-xx {
  display: flex;
  flex-direction: row;
  justify-content: center; // para alinhar horizontalmente
  align-items: center;  // para alinhar verticalmente
}

