.rtc-grid-generico-4 {
  display: grid;
  max-width: 100vw;
  grid-template-columns: repeat(4, 1fr);
  column-gap: 0px;
  row-gap: 0px;
}

.rtc-grid-generico-8 {
  display: grid;
  max-width: 100vw;
  grid-template-columns: repeat(8, 1fr);
  column-gap: 0px;
  row-gap: 0px;
}

.rtc-grid-generico-12 {
