/* Ajustes de compatibilidade e outros aspectos para o correto funcionamento */

:root {
    --ngx-br-size-small: 32px;
	--ngx-br-size-medium: 40px;
	--ngx-br-size-large: 48px;
    --popover-color: #155BCB;
    --tooltip-color: var(--popover-color);
}

/* manter compatibilidade das classes dos buttons com o prefixo "is-" */

.br-button.is-primary:not(:focus):not(:hover):not(:active),
.br-button[is-primary]:not(:focus):not(:hover):not(:active) {
    background: var(--color-primary-default);
    color: var(--color-secondary-01);
}

.br-button.is-secondary, .br-button[is-secondary] {
    border-color: var(--color-primary-default);
}

/* Impedir que as tabs se desconfigurem */
.br-tabs .tab-nav {
	flex-direction: column;
}

/* Pequena margem em botões consecutivos  */
.br-button + .br-button {
    margin-left: 3px;
}

.br-card .card-header {
	padding: .75rem 1.25rem;
}

.br-card .card-footer {
	background-color: unset;
    border-top: unset;
}

.br-header a {
    text-decoration: none;
    pointer-events: none;
}

.br-header a[href] {
    pointer-events: all;
}

/* Corrigir icone para avatar */
.br-avatar .image .fa {
	--icon-size: var(--avatar-size);
	margin-top: 0;
}

body.high-contrast * {
    background-color: black !important;
    color: white  !important;
}

form .button-panel {
	display: flex;
	flex-direction: row;
	justify-content: space-evenly;
	width: 100%;
	margin: 30px 0 25px 0;
}

/* Erros nos formulários */

.br-radio input:invalid + label::before {
    border-color: unset;
}

/* Para o input */
form.ng-submitted .brx-input.ng-invalid:not(:focus-within),
.brx-input-wrapper.ng-invalid.ng-touched .brx-input:not(:focus-within),
.brx-input-wrapper.ng-invalid.ng-dirty   .brx-input:not(:focus-within),

form.ng-submitted .br-radio .brx-input.ng-invalid + label::before,
.brx-input-wrapper.ng-invalid.ng-touched .br-radio .brx-input + label::before,
.brx-input-wrapper.ng-invalid.ng-dirty   .br-radio .brx-input + label::before {
	border-color: var(--danger);
	border-width: 2px;
}

.success-borders form.ng-submitted .brx-input.ng-valid:not(:focus-within),
.success-borders .brx-input-wrapper.ng-valid.ng-touched .brx-input:not(:focus-within),
.success-borders .brx-input-wrapper.ng-valid.ng-dirty   .brx-input:not(:focus-within) {
	border-color: var(--success);
	border-width: 2px;
}

/* Para as mensagens de validacao */

.brx-input-wrapper .feedback {
    width: fit-content;
    display: none;
}

form.ng-submitted .brx-input-wrapper.ng-valid .show-valid-feedback .valid-feedback,
.brx-input-wrapper.ng-valid.ng-touched        .show-valid-feedback .valid-feedback,
.brx-input-wrapper.ng-valid.ng-dirty          .show-valid-feedback .valid-feedback {
    display: inline-block;
    margin-top: 0;
}

form.ng-submitted .brx-input-wrapper.ng-invalid  .invalid-feedback,
.brx-input-wrapper.ng-invalid.ng-touched         .invalid-feedback,
.brx-input-wrapper.ng-invalid.ng-dirty           .invalid-feedback {
    display: inline-block;
    margin-top: 0;
}

.invalid-feedback .message {
	margin-right: 5px;
}

form.ng-submitted .brx-input-wrapper.ng-invalid .feedback,
.brx-input-wrapper.ng-invalid.ng-touched        .feedback,
.brx-input-wrapper.ng-invalid.ng-dirty          .feedback:not(.only-partial) {
	--message-background: var(--danger-alternative);
	--feedback-background: var(--danger);
	--message-color-icon: var(--danger);
    display: block;
}

form.ng-submitted .brx-input-wrapper.ng-valid .show-valid-feedback.feedback,
.brx-input-wrapper.ng-valid.ng-touched        .show-valid-feedback.feedback,
.brx-input-wrapper.ng-valid.ng-dirty          .show-valid-feedback.feedback {
    --message-background: var(--success-alternative);
    --feedback-background: var(--success);
    --message-color-icon: var(--success);
    display: block;
}

form.ng-submitted .brx-input-wrapper.ng-valid   .feedback .message,
form.ng-submitted .brx-input-wrapper.ng-invalid .feedback .message,
.brx-input-wrapper.ng-invalid.ng-touched        .feedback .message,
.brx-input-wrapper.ng-invalid.ng-dirty          .feedback .message,
.brx-input-wrapper.ng-valid.ng-touched          .feedback .message,
.brx-input-wrapper.ng-valid.ng-dirty            .feedback .message {
    font-size: var(--font-size);
    color: var(--message-text);
}

form.ng-submitted .brx-input-wrapper.ng-valid   .feedback .fa-check-circle,
form.ng-submitted .brx-input-wrapper.ng-invalid .feedback .fa-times-circle,
.brx-input-wrapper.ng-invalid.ng-touched        .feedback .fa-times-circle,
.brx-input-wrapper.ng-invalid.ng-dirty          .feedback .fa-times-circle,
.brx-input-wrapper.ng-valid.ng-touched          .feedback .fa-check-circle,
.brx-input-wrapper.ng-valid.ng-dirty            .feedback .fa-check-circle {
    font-size: var(--icon-size);
    color: var(--message-text);
}

form:not(.ng-submitted) .brx-input-wrapper.ng-untouched .field.br-nspve .feedback {
    display: none;
}
/* End.Erros nos formulários */

/* begin.ng-select */
.brx-input.select-external-container {
    --ngx-br-input-height: var(--ngx-br-size-medium);
}

.brx-input.select-external-container.large {
    --ngx-br-input-height: var(--ngx-br-size-large)
}

.brx-input.select-external-container.small {
    --ngx-br-input-height: var(--ngx-br-size-small)
}

.br-select .ng-select {
    border: 1px solid #888;
    border-radius: 4px;
    min-height: var(--ngx-br-input-height);
    line-height: calc(var(--ngx-br-input-height) - 3px);
    font-size: var(--font-size-scale-up-01);
    margin-top: calc(var(--spacing-scale-half) - 1px);
    margin-bottom: var(--spacing-scale-half);
    padding-left: 1px;
    padding-right: 1px;
}

.br-select .ng-select.ng-select-focused {
    border-color: var(--focus-color);
    box-shadow: 0 0 0 var(--surface-width-md) var(--focus-color);
    outline: none;
}

.br-select .ng-select-disabled {
    border-color: #08080840;
}

.brx-input.select-external-container .ng-select .ng-select-container {
    min-width: 80px;
    border-radius: 4px;
    background: var(--color-secondary-01);
}

.br-select .ng-select-disabled .ng-select-container .ng-value-container .ng-input>input {
    cursor: not-allowed;
}

.br-select .ng-select .ng-select-container .ng-value-container .ng-input>input {
    padding-left: 5px;
    width: calc(100% - 78px);
    margin-left: 25px;
}

.br-select .ng-select-multiple .ng-select-container .ng-value-container .ng-input>input {
    width: calc(100% - 30px);
    margin-left: 0px;
}

.field .br-select .ng-value-container::before {
    content: "\f002";
    font-family: "Font Awesome 5 Free", sans-serif;
    --icon-size: var(--icon-size-base);
    font-size: var(--icon-size);
    text-align: center;
    width: calc(var(--icon-size) + 8px);
    font-weight: 900;
    color: var(--border-color-alternative);
}

.ng-dropdown-panel {
    background: var(--color-secondary-01);
    box-shadow: 0 3px 6px rgba(var(--rgb-secondary-09), .16);
}

.ng-dropdown-panel.ng-select-bottom {
    top: 100%;
    margin-top: 3px;
}

.br-select .ng-select.ng-select-focused .ng-dropdown-panel.ng-select-bottom {
    margin-top: 5px;
}

.ng-dropdown-panel.ng-select-top {
    bottom: 100%;
    margin-bottom: 3px;
}

.br-select .ng-select.ng-select-focused .ng-dropdown-panel.ng-select-top {
    margin-bottom: 5px;
}

.ng-dropdown-panel.ng-select-right {
    left: calc(100% + 3px);
    top: 0;
}

.ng-dropdown-panel.ng-select-left {
    left: -100%;
    top: 0;
}

.ng-dropdown-panel div.ng-dropdown-panel-items div.ng-option {
    font-size: var(--font-size-scale-base);
    font-weight: var(--font-weight-medium);
}

.ng-dropdown-panel div.ng-dropdown-panel-items div.ng-option-selected {
    background: #2670e8;
}

.ng-dropdown-panel div.ng-dropdown-panel-items div.ng-option-selected .br-checkbox label,
.ng-dropdown-panel div.ng-dropdown-panel-items div.ng-option-selected span {
    color: #fff;
}

.br-select .ng-select .ng-placeholder {
    color: var(--text-color);
    font-size: var(--font-size-scale-base);
    font-style: italic;
    font-weight: var(--font-weight-regular);
    opacity: 0.75;
    z-index: 1;
}

.br-select .ng-select.ng-select-multiple .ng-select-container .ng-value-container .ng-placeholder {
	position: static;
}

.br-select .ng-select .ng-has-value .ng-placeholder {
    display: none;
}

.br-select .ng-select .ng-select-container .ng-value-container {
    padding: 0 8px;
    align-items: center;
}

.br-select .ng-select .ng-value-container .ng-value-icon {
    display: none;
}

.br-select .ng-select .ng-value {
    padding-right: 5px;
    z-index: 1;
}

.br-select .ng-select-disabled .ng-value {
    color: rgba(var(--rgb-secondary-08), .45);
}

/* 2.0.1 */
div.ng-dropdown-panel-items div.ng-option {
    padding: var(--spacing-scale-base)
}

div.ng-dropdown-panel-items div.ng-option:not(:last-child) {
    border-bottom: 1px solid var(--color-secondary-04);
}

.br-select .ng-select .ng-arrow-wrapper:hover:before {
    border-radius: 50%;
    background-image: linear-gradient(rgba(var(--rgb-primary-default), var(--hover)), rgba(var(--rgb-primary-default), var(--hover)));
}

.br-select .ng-select .ng-arrow-wrapper::before {
    display: inline-block;
    content: "";
    font-family: "Font Awesome 5 Free", sans-serif;
    font-weight: 900;
    color: #1351b4;
    font-size: var(--font-size-scale-up-01);
    line-height: 20px;
    text-rendering: auto;
    right: 5px;
    top: 50%;
    position: absolute;
    margin: 0;
    transform: translate(0, -50%);
    padding: 2px 4px;
    z-index: 2;
}

.br-select .ng-select .ng-clear-wrapper::before {
    display: inline-block;
    content: "\f12d";
    font-family: "Font Awesome 5 Free", sans-serif;
    font-weight: 900;
    color: #1351b4;
    font-size: var(--font-size-scale-up-01);
    line-height: 20px;
    text-rendering: auto;
    right: 5px;
    top: 50%;
    position: absolute;
    margin: 0;
    transform: translate(-23px, -50%);
    padding: 2px 4px;
    z-index: 2;
}

.br-select .ng-select .ng-clear-wrapper:hover:before {
    border-radius: 50%;
    background-image: linear-gradient(rgba(var(--rgb-primary-default), var(--hover)), rgba(var(--rgb-primary-default), var(--hover)));
}

/* não mostrar o 'x' padrão */
.br-select .ng-select span.ng-clear-wrapper span.ng-clear {
    display: none;
}

.br-selected .ng-select-disabled .ng-arrow-wrapper:before {
    color: #1351b440
}

/* Remover simbolo dropdown default */
.br-select .ng-select > .ng-select-container .ng-arrow {
    border: none;
}

.br-select .ng-select .ng-clear-wrapper .ng-clear {
    color: #1351b4;
    font-size: var(--font-size-scale-up-03);
    font-weight: 600;
    line-height: var(--line-height);
}

div.ng-dropdown-panel-items div.ng-option-marked {
    background-color: transparent;
}

.br-select .ng-select:not(.ng-select-disabled):hover,
.br-select .ng-select:not(.ng-select-disabled) .ng-select-container:hover {
    background-image: linear-gradient(rgba(var(--color-rgb), var(--hover)), rgba(var(--color-rgb), var(--hover))) !important;
}

.br-select {
	max-width: unset;
}

/* end.ng-select */

.br-input.small  {
    --icon-size-base: 12px;
}
.br-input.small.has-icon .br-button.small  {
    --button-size: 24px;
}


[readonly] {
    opacity: var(--disabled);
}

/* onboarding */
.shepherd-title {
    color: var(--pure-0);
    flex: 1 0 auto;
    font-size: var(--font-size-scale-up-01);
    font-weight: var(--font-weight-semi-bold);
    margin: 0;
    padding: 0;
    text-align: center;
  }

  /* Header Styles */
  .shepherd-header {
    font-size: var(--font-size-scale-base);
    align-items: center;
    border-top-left-radius: 5px;
    border-top-right-radius: 5px;
    display: flex;
    justify-content: flex-end;
    line-height: 2em;
    padding: .75rem .75rem 0;
  }

  /* Text Styles */
  .shepherd-text {
    color: var(--pure-0);
    font-size: var(--font-size-scale-up-01);
    line-height: 1.3em;
    padding: .75em;
    font-weight: var(--font-weight-medium);
    text-align: center;
  }

  .shepherd-text p {
    margin-top: 0;
  }

  .shepherd-text p:last-child {
    margin-bottom: 0;
  }

  /* Content Styles */
  .shepherd-content {
    border-radius: 5px;
    outline: none;
    padding: 0;
  }

  /* Element Styles */
  .shepherd-element {
    background: var(--blue-warm-vivid-60);
    border-radius: 5px;
    box-shadow: 0 3px 6px rgba(0, 0, 0, .16);
    max-width: 300px;
    opacity: 0;
    outline: none;
    transition: opacity .3s, visibility .3s;
    visibility: hidden;
    width: 100%;
    z-index: 9999;
    padding: var(--spacing-scale-2x);
  }

  .shepherd-enabled.shepherd-element {
    opacity: 1;
    visibility: visible;
  }

  .shepherd-element[data-popper-reference-hidden]:not(.shepherd-centered) {
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
  }

  .shepherd-element,
  .shepherd-element *,
  .shepherd-element :after,
  .shepherd-element :before {
    box-sizing: border-box;
  }

  /* Arrow Styles */
  .shepherd-arrow,
  .shepherd-arrow:before {
    height: 16px;
    position: absolute;
    width: 16px;
    z-index: -1;
  }

  .shepherd-arrow:before {
    background: var(--blue-warm-vivid-60);
    content: "";
    transform: rotate(45deg);
  }

  .shepherd-element[data-popper-placement^=top] > .shepherd-arrow {
    bottom: -8px;
  }

  .shepherd-element[data-popper-placement^=bottom] > .shepherd-arrow {
    top: -8px;
  }

  .shepherd-element[data-popper-placement^=left] > .shepherd-arrow {
    right: -8px;
  }

  .shepherd-element[data-popper-placement^=right] > .shepherd-arrow {
    left: -8px;
  }

  .shepherd-element.shepherd-centered > .shepherd-arrow {
    opacity: 0;
  }

  .shepherd-element.shepherd-has-title[data-popper-placement^=bottom] > .shepherd-arrow:before {
    background: var(--blue-warm-vivid-60);
  }

  /* Target Click Disabled Styles */
  .shepherd-target-click-disabled.shepherd-enabled.shepherd-target,
  .shepherd-target-click-disabled.shepherd-enabled.shepherd-target * {
    pointer-events: none;
  }

  /* Modal Overlay Container Styles */
  .shepherd-modal-overlay-container {
    height: 0;
    left: 0;
    opacity: 0;
    overflow: hidden;
    pointer-events: none;
    position: fixed;
    top: 0;
    transition: all .3s ease-out, height 0ms .3s, opacity .3s 0ms;
    width: 100vw;
    z-index: 9997;
  }

  .shepherd-modal-overlay-container.shepherd-modal-is-visible {
    height: 100vh;
    opacity: .5;
    transform: translateZ(0);
    transition: all .3s ease-out, height 0s 0s, opacity .3s 0s;
  }

  .shepherd-modal-overlay-container.shepherd-modal-is-visible path {
    pointer-events: all;
  }


  .popover[role="tooltip"] {
    border: none;
    border-top-left-radius: 4px ;
    border-top-right-radius: 4px ;
}

.popover .popover-title.popover-header {
    margin-top: 0;
    color: var(--color-secondary-01, #fff) ;
    background-color: var(--popover-color);
    border-bottom: 1px solid var(--color-secondary-01, #fff) ;
}

.popover .popover-content.popover-body {
    box-shadow: 0 3px 6px rgba(0, 0, 0, 0.16) ;
    background: var(--popover-color) ;
    color: var(--color-secondary-01, #fff) ;
    font-size: var(--font-size-scale-down-01, 11.662px) ;
    font-weight: var(--font-weight-medium, 500) ;
    justify-content: flex-start ;
    border: none;
    border-radius: 4px;
}

.popover .popover-title.popover-header + .popover-content.popover-body {
    border-top-left-radius: 0;
    border-top-right-radius: 0;
}

.popover.bs-popover-left>.popover-arrow.arrow::before {
    border-left-color: transparent;
}

.popover.bs-popover-right>.popover-arrow.arrow::before {
    border-right-color: transparent;
}

.popover.bs-popover-bottom>.popover-arrow.arrow::before {
    border-bottom-color: transparent;
}

.popover.bs-popover-top>.popover-arrow.arrow::before {
    border-top-color: transparent;
}

.popover.bs-popover-left>.popover-arrow.arrow::after {
    border-left-color: var(--popover-color);
}

.popover.bs-popover-right>.popover-arrow.arrow::after {
    border-right-color: var(--popover-color);
}

.popover.bs-popover-bottom>.popover-arrow.arrow::after {
    border-bottom-color: var(--popover-color);
}

.popover.bs-popover-top>.popover-arrow.arrow::after {
    border-top-color: var(--popover-color);
}

.tooltip .tooltip-inner {
    background: var(--color-info, var(--popover-color)) ;
    border-radius: 4px ;
    box-shadow: 0 3px 6px rgba(0, 0, 0, 0.16) ;
    color: var(--color-secondary-01, #fff) ;
    font-size: var(--font-size-scale-down-01, 11.662px) ;
    font-weight: var(--font-weight-medium, 500) ;
    justify-content: flex-start ;
    border-color: transparent;
}

.tooltip.bs-tooltip-left>.tooltip-arrow.arrow::before {
    border-left-color: var(--tooltip-color);
}

.tooltip.bs-tooltip-right>.tooltip-arrow.arrow::before {
    border-right-color: var(--tooltip-color);
}

.tooltip.bs-tooltip-bottom>.tooltip-arrow.arrow::before {
    border-bottom-color: var(--tooltip-color);
}

.tooltip.bs-tooltip-top>.tooltip-arrow.arrow::before {
    border-top-color: var(--tooltip-color);
}

.dropdown-menu {
    box-shadow: var(--surface-shadow-sm);
}

.modal-title {
    margin-top: 0;
}